DROP POLICY IF EXISTS "Anyone can record an allowed funnel event" ON public.funnel_events;
CREATE POLICY "Anyone can record an allowed funnel event" ON public.funnel_events FOR INSERT TO anon, authenticated
WITH CHECK ((length(event) <= 64) AND (event = ANY (ARRAY['page_viewed','signup_viewed','signup_submitted','signup_succeeded','signup_failed','onboarding_started','onboarding_completed','go_live_clicked','publish_page_clicked','checkout_redirected','checkout_canceled','email_lead_submitted','referral_submitted','sample_page_viewed','promo_popup_shown','promo_cta_clicked','invite_link_opened','invite_code_entered','invite_landing_viewed','signup_form_started','invite_cta_clicked','cta_clicked','demo_started','demo_completed','page_published','first_ask_prepared','pwa_install_prompted','pwa_installed','pwa_install_cta_shown','pwa_install_cta_clicked','dashboard_viewed','onboarding_step_completed','publish_banner_seen','publish_succeeded','publish_failed','share_tools_viewed','checkout_succeeded','campaigns_tab_viewed','campaign_segment_selected','campaign_preview_viewed','campaign_send_clicked','campaign_sent','campaign_send_failed','referral_page_load_failed']::text[])) AND ((session_id IS NULL) OR (length(session_id) <= 64)) AND ((path IS NULL) OR (length(path) <= 512)) AND ((referrer IS NULL) OR (length(referrer) <= 512)) AND ((user_agent IS NULL) OR (length(user_agent) <= 512)));